// swift-tools-version: 6.0
import PackageDescription

let package = Package(
    name: "ReleaseLens",
    platforms: [.macOS(.v14)],
    products: [
        .library(name: "ReleaseLensCore", targets: ["ReleaseLensCore"]),
        .executable(name: "releaselens", targets: ["releaselens"]),
    ],
    targets: [
        .target(name: "ReleaseLensCore"),
        .executableTarget(name: "releaselens", dependencies: ["ReleaseLensCore"]),
    ]
)

import Foundation
import ReleaseLensCore

let arguments = Array(CommandLine.arguments.dropFirst())
guard arguments.count == 2 || arguments.count == 3,
      arguments.first == "scan",
      arguments.count == 2 || arguments[2] == "--pretty" else {
    FileHandle.standardError.write(Data("Usage: releaselens scan <artifact-path> [--pretty]\n".utf8))
    exit(64)
}

do {
    let summary = try ArtifactScanner().scan(URL(fileURLWithPath: arguments[1]))
    let encoder = JSONEncoder()
    encoder.outputFormatting = arguments.count == 3 ? [.prettyPrinted, .sortedKeys] : [.sortedKeys]
    FileHandle.standardOutput.write(try encoder.encode(summary))
    FileHandle.standardOutput.write(Data("\n".utf8))
} catch {
    FileHandle.standardError.write(Data("\(error.localizedDescription)\n".utf8))
    exit(1)
}

import Foundation

public enum ArtifactKind: String, Codable, Sendable {
    case application, framework, bundle, package, diskImage, directory, file
}

/// Size contribution of a single top-level child (or the "other" aggregate).
public struct ArtifactContribution: Codable, Equatable, Sendable {
    public let name: String
    public let regularFileCount: Int
    public let totalBytes: UInt64

    public init(name: String, regularFileCount: Int, totalBytes: UInt64) {
        self.name = name
        self.regularFileCount = regularFileCount
        self.totalBytes = totalBytes
    }
}

/// The top-level child directory that contributes the most bytes.
///
/// Ties are broken deterministically by name (ascending) and every other
/// contributor sharing the maximum is listed in `tiedWith`, so an exact tie
/// is visible in the output instead of being resolved by enumeration order.
public struct LargestContribution: Codable, Equatable, Sendable {
    public let name: String
    public let regularFileCount: Int
    public let totalBytes: UInt64
    public let tied: Bool
    public let tiedWith: [String]

    public init(name: String, regularFileCount: Int, totalBytes: UInt64, tied: Bool, tiedWith: [String]) {
        self.name = name
        self.regularFileCount = regularFileCount
        self.totalBytes = totalBytes
        self.tied = tied
        self.tiedWith = tiedWith
    }
}

public struct ArtifactSummary: Codable, Equatable, Sendable {
    public let path: String
    public let name: String
    public let kind: ArtifactKind
    public let regularFileCount: Int
    public let symbolicLinkCount: Int
    public let totalBytes: UInt64
    /// Per top-level child directory contributions, sorted by bytes
    /// (descending), then by name (ascending) for deterministic output.
    public let contributions: [ArtifactContribution]
    /// Everything not attributed to a listed top-level directory: the root
    /// item itself, loose regular files at the top level, and symlinks (which
    /// carry no bytes under the scan's counting rules).
    public let otherContribution: ArtifactContribution
    /// The largest contributor, or `nil` when there is no top-level directory
    /// with a non-zero byte contribution.
    public let largestContribution: LargestContribution?

    public init(path: String,
                name: String,
                kind: ArtifactKind,
                regularFileCount: Int,
                symbolicLinkCount: Int,
                totalBytes: UInt64,
                contributions: [ArtifactContribution],
                otherContribution: ArtifactContribution,
                largestContribution: LargestContribution?) {
        self.path = path
        self.name = name
        self.kind = kind
        self.regularFileCount = regularFileCount
        self.symbolicLinkCount = symbolicLinkCount
        self.totalBytes = totalBytes
        self.contributions = contributions
        self.otherContribution = otherContribution
        self.largestContribution = largestContribution
    }

    // The synthesized encoder would omit `largestContribution` when it is nil.
    // The contract wants an explicit `null` so "no largest source" is stated
    // rather than silently absent; plain `encode` of an optional emits null.
    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(path, forKey: .path)
        try container.encode(name, forKey: .name)
        try container.encode(kind, forKey: .kind)
        try container.encode(regularFileCount, forKey: .regularFileCount)
        try container.encode(symbolicLinkCount, forKey: .symbolicLinkCount)
        try container.encode(totalBytes, forKey: .totalBytes)
        try container.encode(contributions, forKey: .contributions)
        try container.encode(otherContribution, forKey: .otherContribution)
        try container.encode(largestContribution, forKey: .largestContribution)
    }

    private enum CodingKeys: String, CodingKey {
        case path, name, kind, regularFileCount, symbolicLinkCount, totalBytes
        case contributions, otherContribution, largestContribution
    }
}

public enum ArtifactScannerError: Error, LocalizedError, Equatable {
    case missing(String)
    case unreadable(String)

    public var errorDescription: String? {
        switch self {
        case .missing(let path): "Artifact does not exist: \(path)"
        case .unreadable(let path): "Artifact cannot be inspected: \(path)"
        }
    }
}

public struct ArtifactScanner: Sendable {
    public init() {}

    public func scan(_ input: URL) throws -> ArtifactSummary {
        let url = input.standardizedFileURL
        let manager = FileManager.default
        guard manager.fileExists(atPath: url.path) else { throw ArtifactScannerError.missing(url.path) }

        let keys: Set<URLResourceKey> = [.isRegularFileKey, .isDirectoryKey, .isSymbolicLinkKey, .fileSizeKey]
        guard let rootValues = try? url.resourceValues(forKeys: keys) else { throw ArtifactScannerError.unreadable(url.path) }

        // The root item's own contribution follows the exact same accounting as
        // the previous scan: its fileSize is counted unconditionally, and it is
        // one regular file when it is one. It is attributed to "other".
        var regularFiles = rootValues.isRegularFile == true ? 1 : 0
        var symbolicLinks = rootValues.isSymbolicLink == true ? 1 : 0
        var bytes = UInt64(max(rootValues.fileSize ?? 0, 0))
        var otherFiles = regularFiles
        var otherBytes = bytes
        var buckets: [String: ArtifactContribution] = [:]

        if rootValues.isDirectory == true {
            // A single enumeration drives both the totals and the breakdown, so
            // hidden-file and package-descendant skipping applies identically
            // to both and no item can be counted in one but missed in the other.
            var enumerationError: URL?
            guard let enumerator = manager.enumerator(
                at: url,
                includingPropertiesForKeys: Array(keys),
                options: [.skipsHiddenFiles, .skipsPackageDescendants],
                errorHandler: { failedURL, _ in
                    enumerationError = failedURL
                    return false
                }
            ) else {
                throw ArtifactScannerError.unreadable(url.path)
            }

            // The depth-first traversal names the current top-level child at
            // every step: whenever an item sits at the root's direct-child
            // depth, a new top-level child begins, and all deeper levels belong
            // to that same child. Depth is measured relative to the first
            // vended item: plain directory roots vend direct children at
            // level 0, while a package root (.app/.framework/…) is treated by
            // the enumerator as a package whose contents start at level 1.
            // Tracking the observed base (instead of assuming 0) handles both
            // with the same rule and avoids comparing paths, which also stays
            // correct when the root is reached through a symlink
            // (e.g. /var -> /private/var).
            var baseLevel: Int?
            var currentTop: String?

            while let child = enumerator.nextObject() as? URL {
                // Any failure reading a single item fails the whole scan: a
                // partial breakdown would not reconcile with the total.
                let values: URLResourceValues
                do {
                    values = try child.resourceValues(forKeys: keys)
                } catch {
                    throw ArtifactScannerError.unreadable(child.path)
                }

                if baseLevel == nil { baseLevel = enumerator.level }
                let isTopLevel = enumerator.level == baseLevel
                if isTopLevel {
                    // A new direct child begins; descendants belong to it.
                    currentTop = child.lastPathComponent
                }

                if values.isSymbolicLink == true {
                    symbolicLinks += 1
                    continue
                }
                guard values.isRegularFile == true else {
                    // A top-level directory opens its own bucket. Directories at
                    // deeper levels and opaque (non-root) packages contribute
                    // nothing themselves; their contained regular files (when
                    // traversed) are attributed to the enclosing top-level child.
                    if isTopLevel, values.isDirectory == true, let topName = currentTop {
                        buckets[topName] = ArtifactContribution(name: topName, regularFileCount: 0, totalBytes: 0)
                    }
                    continue
                }

                let size = UInt64(max(values.fileSize ?? 0, 0))
                regularFiles += 1
                bytes += size

                if isTopLevel || currentTop == nil {
                    // Loose regular file at the top level (or unattributable)
                    // lands in "other".
                    otherFiles += 1
                    otherBytes += size
                } else if let topName = currentTop {
                    // The parent directory is always vended before its
                    // descendants, so the bucket exists; fall back to "other"
                    // defensively, which still keeps the books balanced.
                    if var bucket = buckets[topName] {
                        bucket = ArtifactContribution(
                            name: bucket.name,
                            regularFileCount: bucket.regularFileCount + 1,
                            totalBytes: bucket.totalBytes + size
                        )
                        buckets[topName] = bucket
                    } else {
                        otherFiles += 1
                        otherBytes += size
                    }
                }
            }

            if let failedURL = enumerationError {
                throw ArtifactScannerError.unreadable(failedURL.path)
            }
        }

        // Deterministic ordering independent of filesystem enumeration order:
        // most bytes first, then name ascending.
        let sortedContributions = buckets.values.sorted { lhs, rhs in
            if lhs.totalBytes != rhs.totalBytes { return lhs.totalBytes > rhs.totalBytes }
            return lhs.name < rhs.name
        }

        // Largest source: only directories with an actual, non-zero byte
        // contribution participate. Equal maxima are reported as an explicit
        // tie with the deterministic (name-sorted) winner named.
        let largest: LargestContribution?
        if let maxBytes = sortedContributions.first(where: { $0.totalBytes > 0 })?.totalBytes {
            let leaders = sortedContributions.filter { $0.totalBytes == maxBytes }
            let winner = leaders[0]
            largest = LargestContribution(
                name: winner.name,
                regularFileCount: winner.regularFileCount,
                totalBytes: winner.totalBytes,
                tied: leaders.count > 1,
                tiedWith: leaders.dropFirst().map(\.name)
            )
        } else {
            largest = nil
        }

        let other = ArtifactContribution(name: "other", regularFileCount: otherFiles, totalBytes: otherBytes)

        return ArtifactSummary(
            path: url.path,
            name: url.lastPathComponent,
            kind: kind(for: url, isDirectory: rootValues.isDirectory == true),
            regularFileCount: regularFiles,
            symbolicLinkCount: symbolicLinks,
            totalBytes: bytes,
            contributions: sortedContributions,
            otherContribution: other,
            largestContribution: largest
        )
    }

    private func kind(for url: URL, isDirectory: Bool) -> ArtifactKind {
        switch url.pathExtension.lowercased() {
        case "app": .application
        case "framework": .framework
        case "bundle": .bundle
        case "pkg": .package
        case "dmg": .diskImage
        default: isDirectory ? .directory : .file
        }
    }
}

